fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();

    // Only need to check all parents up to floor(n/2) - 1
    // Since for last nodes in second half of array, they are leaves with no children.
    for i in 0..(n / 2) {
        let left = 2 * i + 1;
        let right = 2 * i + 2;

        // Check left child if exists
        if left < n && a[left] < a[i] {
            return false;
        }

        // Check right child if exists
        if right < n && a[right] < a[i] {
            return false;
        }
    }

    true
}